void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float cell = max(U.p0.x, 3.0);
    float a = radians(U.p0.y);
    mat2 rot = mat2(cos(a), -sin(a), sin(a), cos(a));
    mat2 back = mat2(cos(a), sin(a), -sin(a), cos(a));
    vec2 p = rot * fragCoord;
    vec2 centre = (floor(p / cell) + 0.5) * cell;
    vec3 src = texture(iChannel0, (back * centre) / iResolution.xy).rgb;
    float l = dot(src, vec3(0.2126, 0.7152, 0.0722));
    float radius = sqrt(clamp(1.0 - l, 0.0, 1.0)) * cell * 0.72;
    float ink = 1.0 - smoothstep(radius - 1.0, radius + 1.0, length(p - centre));
    vec3 paper = vec3(0.96, 0.93, 0.86);
    vec3 inkc = mix(vec3(0.07, 0.06, 0.12), src * 0.6, U.p0.z);
    fragColor = vec4(mix(paper, inkc, ink), 1.0);
}
